import { serve } from 'https://deno.land/std@0.224.0/http/server.ts';

serve(async (req) => {
  const { commodity, pricePerKilo } = await req.json();
  if (typeof pricePerKilo !== 'number') {
    return new Response(JSON.stringify({ error: 'pricePerKilo must be a number' }), { status: 400 });
  }
  const alert = pricePerKilo > 200 ? `Mahal ang ${commodity} ngayon` : null;
  return new Response(JSON.stringify({ commodity, alert }), {
    headers: { 'Content-Type': 'application/json' },
  });
});

